#!/usr/bin/env python3
from ta_emss import ta_emss


if __name__ == "__main__":
    emss1 = ta_emss()
    emss1.setup_emss(user='vcu1', bts_ip='192.168.100.129', oam_ip='192.168.100.1/24', alias='cu1')

    # --- SETUP XTERM PARAMS ---
    print("Setting up...")
    emss1.xterm_setup(
        # --- ENDCX2AP PARAMS ---
        bts_ip_addr="10.0.1.10",
        enbsim_ip_addr_begin="10.0.1.31",
        enbsim_ip_addr_end="10.0.1.40",
        enbsim_ip_addr_mask=24,
        enbsim_eth_if="eth3",
        mme_ip_addr="10.253.206.1",
        mme_ip_addr_mask=24,
        mme_eth_if="eth3",
        mme_mcc="244",
        mme_mnc="09",
        mme_code=15,
        mme_group_id=12,
        init_enb_pci_max=503,
        init_enb_enb_id=4001,
        init_enb_mcc="440",
        init_enb_mnc="08",
        init_enb_tac=1,
        init_enb_dl_earfcn=4900,
        init_enb_dl_bandwidth=10,
        x2ap_setup_period=15,
        x2ap_setup_retries=3,
        x2ap_reset_period=15,
        x2ap_reset_retries=3,
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=False
    )

    # --- START X2AP SIMULATION ---
    print("Starting ENDCX2AP simulation...")
    emss1.xterm_start(endcx2ap=True)

    # --- BREAK SIMULATION ---
    while (k := input("Press 'q' to stop...")) != 'q':
        pass

    # --- STOP XTERM ---
    print("Stopping xterm")
    emss1.xterm_teardown()
